from pathlib import Path
import markdown, re, html
root=Path.cwd()
md=(root/'DEVELOPMENT-JOURNEY-V1.md').read_text(encoding='utf-8')
body=markdown.markdown(md,extensions=['tables','toc','fenced_code'])
# The title is presented in the designed hero, not repeated in the article.
body=re.sub(r'^<h1[^>]*>.*?</h1>','',body,count=1)
body=re.sub(r'<table>', '<div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable evidence table"><table>',body).replace('</table>','</table></div>')
body=re.sub(r'href="(docs/evidence/[^"#]*?/)"',r'href="https://github.com/az9713/gpt-6-astra-tennis-game/tree/main/\1"',body)
nav=''.join(f'<a href="#{ident}">{title}</a>' for ident,title in re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',body))
motion='<div class="demo" id="motion-demo"><p class="kicker">Actual captured animation / select a stroke</p><div class="switches" role="group" aria-label="Stroke selection">'
for i,(slug,label) in enumerate([('forehand','Forehand'),('backhand','Backhand'),('smash','Smash'),('serve','Trophy serve')]):
 motion+=f'<button type="button" data-stroke="{slug}" aria-pressed="{str(i==0).lower()}">{label}</button>'
motion+='</div>'
for i,(slug,label) in enumerate([('forehand','Forehand'),('backhand','Backhand'),('smash','Smash'),('serve','Trophy serve')]):
 motion+=f'<video id="stroke-{slug}" aria-label="{label} captured motion" controls playsinline preload="metadata" poster="docs/media/motion-{slug}.png" {"hidden" if i else ""}><source src="docs/media/motion-{slug}.mp4" type="video/mp4">Your browser cannot play this video. <a href="docs/media/motion-{slug}.mp4">Open the clip</a>.</video>'
motion+='<p class="caption">Three-second excerpts from the fixed-step Unity motion viewer. These show the authored stroke; gameplay blends anticipation and shorter contact scheduling.</p><figure><img loading="lazy" src="docs/media/motion-serve-trophy.png" alt="Robot in the authored serve trophy preparation pose"><figcaption>The trophy is a preparation pose within the serve sequence.</figcaption></figure></div>'
speed='''<div class="demo dark" id="speed-demo"><p class="kicker">Explore game time versus real time</p><h3>Same rules. More time to react.</h3><div class="switches" role="group" aria-label="Illustrative practice speed"><button data-speed="1" aria-pressed="false">Normal</button><button data-speed="0.5" aria-pressed="false">Half</button><button data-speed="0.25" aria-pressed="true">Quarter</button></div><div class="timing" aria-live="polite"><p><span>Early swing buffer</span><strong id="buffer-time">1.92 real seconds</strong><small>0.48 game seconds</small></p><p><span>Example hitting window</span><strong id="window-time">2.40 real seconds</strong><small>0.60 game seconds, if otherwise unchanged</small></p></div><div class="meter"><span id="time-meter" style="width:100%"></span></div><p id="speed-explanation">Quarter speed gives four times the real time for the same game-time interval.</p><p class="caption">An explanatory calculator, not the game itself. It does not guarantee a particular window for every shot or change the real game speed.</p></div>'''
comparison='''<figure class="demo" id="ui-demo"><p class="kicker">Actual Windows captures / inspect the change</p><div class="switches" role="group" aria-label="UI comparison"><button data-ui="pause-before" aria-pressed="false">Before: center modal</button><button data-ui="pause-after" aria-pressed="true">After: side panel</button><button data-ui="court-after" aria-pressed="false">During play</button><button data-ui="result-after" aria-pressed="false">Match result</button></div><img id="ui-image" loading="lazy" src="docs/media/v1/pause-after.png" alt="Redesigned pause screen with controls at the left and center court visible"><figcaption id="ui-caption">v0.4.1: two edge bars and a contextual left panel. Captures show different synthetic-test moments; this is a layout comparison, not the same rally replayed.</figcaption></figure>'''
body=body.replace('<!-- MOTION_GALLERY -->',motion).replace('<!-- SPEED_LAB -->',speed).replace('<!-- UI_COMPARISON -->',comparison)
css='''
:root{--paper:#f4f0e7;--ink:#173c34;--muted:#5c7168;--line:#cbd5c8;--clay:#bc573a;--light:#e1e8d6}*{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.8 system-ui,Segoe UI,sans-serif}a{color:#246f60;text-underline-offset:4px}a:hover{color:var(--clay)}button{font:inherit;cursor:pointer;border:1px solid #91aa9b;background:transparent;color:inherit;border-radius:5px;padding:9px 14px}button[aria-pressed=true]{background:var(--ink);color:var(--paper);border-color:var(--ink)}:focus-visible{outline:3px solid #d07043;outline-offset:4px}.skip{position:absolute;top:-80px;padding:12px;background:white;z-index:4}.skip:focus{top:5px}.mast{background:var(--ink);color:var(--paper);padding:20px 5vw;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font-size:12px;letter-spacing:.06em}.mast a{color:#d9e7c2}.hero{background:var(--ink);color:var(--paper);padding:56px 5vw 68px}.kicker{text-transform:uppercase;letter-spacing:.12em;font-size:12px;font-weight:700}.hero .kicker{color:#aad3b4}.hero h1{font:clamp(45px,6vw,84px)/1.05 Georgia,serif;letter-spacing:-.035em;max-width:1000px;margin:22px 0 30px}.hero h1 em{color:#e69870}.hero .intro{max-width:830px;font-size:21px;color:#d5e2d0;line-height:1.65}.hero img{display:block;width:100%;margin-top:38px;border-radius:6px}.hero figure{margin:0}.hero figcaption{color:#cbdbca;font-size:12px;margin-top:12px}.versions{display:flex;flex-wrap:wrap;gap:12px 25px;border-bottom:1px solid var(--line);padding:21px 5vw;font-size:14px}.versions span{white-space:nowrap}.versions b{margin-right:6px}.layout{max-width:1440px;margin:auto;display:grid;grid-template-columns:230px minmax(0,950px);gap:45px;padding:60px 4vw}.side{position:sticky;top:24px;align-self:start;max-height:92vh;overflow:auto;font-size:12px}.side nav a{display:block;padding:10px 0 10px 12px;border-left:2px solid var(--line);text-decoration:none;line-height:1.45}.side nav a:hover{border-left-color:var(--clay)}.side button{margin-top:18px;font-size:13px}main{min-width:0}h2{font:38px/1.22 Georgia,serif;letter-spacing:-.02em;padding-top:44px;margin-top:64px;border-top:1px solid var(--line);scroll-margin-top:20px}h3{font:26px/1.4 Georgia,serif;margin-top:34px}p{margin:19px 0}blockquote{margin:26px 0;border-left:3px solid var(--clay);background:#e9eadf;padding:9px 23px}blockquote p{margin:10px 0}li{margin:13px 0}code{font:13px/1.7 Consolas,monospace;background:#e5e9df;padding:2px 4px;overflow-wrap:anywhere}.table-scroll{overflow-x:auto;margin:28px 0}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.6}td,th{padding:13px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}th{background:#dee6d4}main img{width:100%;height:auto;display:block;border-radius:4px}video{width:100%;aspect-ratio:16/9;background:#172c29;display:block;border-radius:4px}.demo{margin:38px 0;padding:24px;border:1px solid var(--line);border-radius:7px;background:#e8ecdf}.demo h3{margin-top:12px}.switches{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0 22px}.switches button{font-size:14px}.caption,figcaption{font-size:13px;color:var(--muted);line-height:1.65}.demo figure{margin:26px 0 0}.demo figure img{max-width:500px;margin:auto}.demo figcaption{margin-top:14px}.dark{background:var(--ink);color:var(--paper);border:0}.dark .kicker{color:#b8d8b8}.dark .caption{color:#cedbca}.dark button[aria-pressed=true]{background:#edc09d;color:var(--ink)}.timing{display:grid;grid-template-columns:1fr 1fr;gap:24px}.timing span,.timing strong,.timing small{display:block}.timing span{font-size:14px;color:#c9d9c5}.timing strong{font:30px Georgia,serif;margin:12px 0}.timing small{font-size:12px;color:#c9d9c5}.meter{height:9px;background:#476658;border-radius:5px;overflow:hidden}.meter span{display:block;height:100%;background:#edc09d;transition:width .3s}footer{padding:35px 5vw;background:var(--ink);color:var(--paper);font-size:13px}footer a{color:#d6e4b9}@media(max-width:1000px){.layout{grid-template-columns:185px minmax(0,1fr);gap:25px}.hero .intro{font-size:19px}}@media(max-width:720px){body{font-size:16px}.layout{display:block;padding:28px 6vw}.side{position:static;max-height:none;margin-bottom:32px}.side nav{display:grid;grid-template-columns:1fr 1fr;gap:4px}.side nav a{font-size:11px}.hero{padding:35px 6vw}.hero h1{font-size:47px}.hero .intro{font-size:18px}.versions{font-size:12px;padding:18px 6vw}.demo{padding:16px}.timing{grid-template-columns:1fr;gap:0}.timing strong{font-size:28px}h2{font-size:32px}td,th{min-width:145px;padding:10px}.mast{font-size:11px}.caption{overflow-wrap:anywhere}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.meter span{transition:none}}@media print{.side,.mast,.switches,video{display:none}.layout{display:block;padding:0}.hero{background:white;color:black;padding:0}.hero .intro{color:black}.hero h1{font-size:40px}.hero h1 em{color:black}.hero img{max-width:600px}.versions{padding:10px 0}body{background:white;color:black;font-size:11pt}h2{font-size:24pt;break-after:avoid}h3{break-after:avoid}.demo,.dark{background:#eee;color:black}.dark .caption,.timing span,.timing small{color:black}.table-scroll{overflow:visible}footer{background:white;color:black}}
'''
js='''
document.querySelector('#print').onclick=()=>window.print();
document.querySelectorAll('[data-stroke]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-stroke]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('#motion-demo video').forEach(v=>{v.pause();v.hidden=v.id!=='stroke-'+button.dataset.stroke})});
document.querySelectorAll('[data-speed]').forEach(button=>button.onclick=()=>{let speed=Number(button.dataset.speed);document.querySelectorAll('[data-speed]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('#buffer-time').textContent=(.48/speed).toFixed(2)+' real seconds';document.querySelector('#window-time').textContent=(.60/speed).toFixed(2)+' real seconds';document.querySelector('#time-meter').style.width=(25/speed)+'%';document.querySelector('#speed-explanation').textContent=speed===1?'Normal speed: game time and real time advance together.':speed===.5?'Half speed gives twice the real time for the same game-time interval.':'Quarter speed gives four times the real time for the same game-time interval.'});
const captions={'pause-before':'v0.4: the center pause modal hides the court amid separate HUD cards.','pause-after':'v0.4.1: two edge bars and a left pause panel leave center court visible.','court-after':'v0.4.1 during play: only two persistent edge bars.','result-after':'v0.4.1: the match result stays in the left margin.'};document.querySelectorAll('[data-ui]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-ui]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let key=button.dataset.ui;document.querySelector('#ui-image').src='docs/media/v1/'+key+'.png';document.querySelector('#ui-image').alt=captions[key];document.querySelector('#ui-caption').textContent=captions[key]+' Captures show different synthetic-test moments; this compares layouts, not identical rally frames.'});
'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="The second Robo Open development journey: robot strokes, skin repair, return planning, local diagnostics, slow-motion practice and a quieter UI. Human decisions, implementation failures and evidence."><title>Robo Open v1 — Gameplay Enhancements</title><style>{css}</style></head><body><a class="skip" href="#journey">Skip to the journey</a><header class="mast"><span>ROBO OPEN / SECOND-ROUND FIELD NOTES</span><span><a href="JOURNEYS.html" target="_top">Journey tabs</a> · <a href="DEVELOPMENT-JOURNEY.html" target="_top">Original journey</a> · <a href="DEVELOPMENT-JOURNEY-V1.md">Markdown source</a></span></header><section class="hero"><p class="kicker">v1 / Gameplay enhancements</p><h1>The robots learned to move.<br>The game learned to <em>listen.</em></h1><p class="intro">Four strokes were only the beginning. Human play revealed missing inputs, unforgiving forecasts, hidden evidence and too much interface. This is how those observations became a more learnable tennis prototype.</p><figure><img src="docs/media/v1/court-after.png" alt="Current local Windows tennis build with two slim edge bars and an unobstructed center court"><figcaption>Actual v0.4.1 Windows capture. “v1” names this narrative, not a v1.0 software release.</figcaption></figure></section><div class="versions"><span><b>v0.2</b> Coordinated motion</span><span><b>v0.3</b> Returns + diagnosis</span><span><b>v0.4</b> Slow practice</span><span><b>v0.4.1</b> Two-bar UI</span></div><div class="layout"><aside class="side"><p class="kicker">Read the full account</p><nav aria-label="Journey sections">{nav}</nav><button id="print">Print / save as PDF</button></aside><main id="journey">{body}</main></div><footer>Independent reconstruction inspired by <a href="https://www.youtube.com/watch?v=DQfL_l5lRpk">Chong-U’s video</a>. Original journey preserved. Raw human session logs remain local. <a href="https://github.com/az9713/gpt-6-astra-tennis-game">Repository</a>.</footer><script>{js}</script></body></html>'''
(root/'DEVELOPMENT-JOURNEY-V1.html').write_text(page,encoding='utf-8')
print('Wrote v1 HTML:',len(page),'characters;',len(re.findall(r'<h2 ',body)),'sections')
